css:
.ax{
  --bg:#ffffff; --fg:#0f1720; --body:#2a343d; --muted:#5b6670; --rule:#dfe5ea; --panel:#f3f6f8;
  --accent:#0b6b7a; --hot:#b42318; --c2:#8a4b9e; --bar:#8aa0ad; --ref:#c4ccd2; --strip:#0f1720; --strip-fg:#ffffff;
  --note-bg:#fff7e0; --note-bd:#b08400; --note-fg:#4d3b00; --link:#0b6b7a; --key:#e8f2f4;
  --font:"IBM Plex Sans",system-ui,-apple-system,"Segoe UI",sans-serif;
;}html.dark .ax{
  --bg:#0e1419; --fg:#eef2f5; --body:#c9d2d9; --muted:#97a3ad; --rule:#2b363f; --panel:#161e25;
  --accent:#5cc0d0; --hot:#f2766b; --c2:#c79be0; --bar:#6f8795; --ref:#4a5963; --strip:#000000; --strip-fg:#ffffff;
  --note-bg:#2a2410; --note-bd:#b08400; --note-fg:#f0dca0; --link:#5cc0d0; --key:#14262b; color-scheme:dark;}.ax{color:var(--fg);font-family:var(--font)}
.ax .kick{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);font-weight:700}
.ax h1{font-size:clamp(28px,6vw,40px);line-height:1.12;margin:12px 0 16px;text-wrap:balance;color:var(--fg)}
.ax .lede{font-size:19px;line-height:1.55;color:var(--body);margin:0 0 14px}
.ax h2{font-size:24px;line-height:1.25;margin:48px 0 12px;text-wrap:balance;color:var(--fg)}
.ax h3{font-size:17px;margin:22px 0 6px;color:var(--fg)}
.ax p{font-size:17px;line-height:1.65;color:var(--body);margin:0 0 14px}
.ax a{color:var(--link)}
.ax sup a{text-decoration:none;font-size:.75em;padding:0 1px}
.ax .key{background:var(--key);border-radius:10px;padding:16px 18px;margin:20px 0}
.ax .key b{display:block;font-size:12px;letter-spacing:.07em;text-transform:uppercase;color:var(--accent);margin-bottom:6px}
.ax .key p{margin:0 0 10px;font-size:17px;color:var(--fg)}
.ax .key p:last-child{margin-bottom:0}
.ax .fig{background:var(--panel);border-radius:10px;padding:20px 20px 14px;margin:22px 0}
.ax .fig h3{font-size:15px;margin:0 0 10px}
.ax .fig svg{display:block;max-width:100%;height:auto}
.ax .cap{font-size:13px;color:var(--muted);line-height:1.5;margin:10px 0 0}
.ax .steps{display:grid;gap:12px;margin:18px 0;padding:0;list-style:none;counter-reset:s}
.ax .steps li{display:grid;grid-template-columns:auto minmax(0,1fr);gap:4px 14px;align-items:start}
.ax .steps li::before{counter-increment:s;content:counter(s);width:28px;height:28px;border-radius:50%;background:var(--accent);color:var(--bg);font-weight:700;font-size:14px;display:flex;align-items:center;justify-content:center;grid-row:1 / span 2}
.ax .steps b{font-size:17px;color:var(--fg)}
.ax .steps span{font-size:16px;line-height:1.6;color:var(--body)}
.ax .limit{border:1px solid var(--rule);border-radius:10px;padding:16px 18px;margin:24px 0}
.ax .limit b{display:block;font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin-bottom:8px}
.ax .limit ul{margin:0;padding-left:18px}
.ax .limit li{font-size:15px;line-height:1.6;color:var(--body);margin-bottom:6px}
.ax .faq h3{margin-top:20px}
.ax .q{border:2px solid var(--accent);border-radius:10px;padding:18px 20px;margin:22px 0}
.ax .q b{display:block;font-size:12px;letter-spacing:.07em;text-transform:uppercase;color:var(--accent);margin-bottom:6px}
.ax .q p{margin:0;font-size:20px;line-height:1.45;color:var(--fg);font-weight:500}
.ax .etape{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);font-weight:700;margin:52px 0 0}
.ax .etape + h2{margin-top:6px}
.ax .toc{margin:16px 0 8px;padding:0;list-style:none;display:grid;gap:6px}
.ax .toc li{font-size:15px;color:var(--body);line-height:1.5}
.ax .toc b{color:var(--fg)}
.ax .list{margin:0 0 14px;padding-left:20px}
.ax .list li{font-size:17px;line-height:1.6;color:var(--body);margin-bottom:8px}
.ax .src{font-size:13px;color:var(--muted);line-height:1.7;padding-left:22px}
.ax .src li{margin-bottom:6px;overflow-wrap:anywhere}
.ax .legend{display:flex;flex-wrap:wrap;gap:6px 18px;margin:0 0 10px;font-size:13px;color:var(--body)}
.ax .legend i{display:inline-block;width:22px;height:0;border-top:3px solid var(--accent);vertical-align:middle;margin-right:6px}
.ax .legend i.f{border-top-color:var(--c2)}
.ax .ctl{display:flex;flex-wrap:wrap;gap:10px 16px;align-items:end;margin:0 0 12px}
.ax .ctl > div{min-width:0}
.ax .ctl .grow{flex:1 1 220px}
.ax .ctl label{display:block;font-size:12px;color:var(--muted);margin-bottom:4px}
.ax select,.ax button{font:inherit;font-size:15px;padding:7px 10px;border:1px solid var(--rule);border-radius:6px;background:var(--bg);color:var(--fg)}
.ax button{cursor:pointer}
.ax button:hover{border-color:var(--accent)}
.ax select:focus-visible,.ax button:focus-visible,.ax input:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.ax input[type=range]{width:100%;accent-color:var(--accent);margin:4px 0}
.ax .presets{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 10px}
.ax .presets button{font-size:13px;padding:5px 9px}
.ax .readout{font-size:15px;line-height:1.55;color:var(--fg);margin:8px 0 0;min-height:4.6em}
.ax .readout b{font-weight:600}
.ax svg .grid{stroke:var(--rule);stroke-width:1}
.ax svg .grid.base{stroke:var(--muted);stroke-dasharray:4 4}
.ax svg .bar{fill:var(--bar)}
.ax svg .hot{fill:var(--hot)}
.ax svg .ref{fill:var(--ref)}
.ax svg .acc{fill:var(--accent)}
.ax svg .hotc{fill:var(--hot)}
.ax svg .c2{fill:var(--c2)}
.ax svg .lab{font:12px var(--font);fill:var(--body)}
.ax svg .tick{font:11px var(--font);fill:var(--muted)}
.ax svg .val{font:600 13px var(--font);fill:var(--fg);paint-order:stroke;stroke:var(--panel);stroke-width:3px;stroke-linejoin:round}
.ax svg .note-t{font:600 11px var(--font);fill:var(--accent);paint-order:stroke;stroke:var(--panel);stroke-width:3px;stroke-linejoin:round}
.ax svg .arrow{stroke:var(--accent);stroke-width:2;fill:none}
.ax svg .bandm{fill:var(--accent);fill-opacity:.14}
.ax svg .bandf{fill:var(--c2);fill-opacity:.16}
.ax svg .draw{fill:none;stroke-width:3;stroke-linejoin:round;stroke-linecap:round;stroke-dasharray:1;stroke-dashoffset:0}
.ax svg .lm{stroke:var(--accent)}
.ax svg .lf{stroke:var(--c2)}
.ax svg .dm{fill:var(--accent)}
.ax svg .df{fill:var(--c2)}
.ax svg .thr{stroke:var(--muted);stroke-width:1.5;stroke-dasharray:5 4}
.ax svg .err{stroke:var(--fg);stroke-width:2;fill:none}
.ax svg .curve{fill:none;stroke:var(--accent);stroke-width:2.5}
.ax svg .shade{fill:var(--accent);fill-opacity:.28}
.ax svg .cur{stroke:var(--hot);stroke-width:2.5}
.ax #cmp .lab,.ax #cmp .tick{paint-order:stroke;stroke:var(--panel);stroke-width:3px;stroke-linejoin:round}
.ax svg .curt{font:600 13px var(--font);fill:var(--fg)}
.ax svg .dash{stroke:var(--hot);stroke-width:1.5;stroke-dasharray:4 3}
.ax svg .medl{stroke:var(--accent);stroke-width:2}
.ax svg .gv{transform-box:fill-box;transform-origin:50% 100%}
.ax svg .gh{transform-box:fill-box;transform-origin:0 50%}
.ax svg .gc{transform-box:fill-box;transform-origin:50% 50%}
.ax .play svg .gv{animation:ax-gv .9s cubic-bezier(.2,.7,.2,1) both;animation-delay:var(--d,0s)}
.ax .play svg .gh{animation:ax-gh .9s cubic-bezier(.2,.7,.2,1) both;animation-delay:var(--d,0s)}
.ax .play svg .gc{animation:ax-gh .8s cubic-bezier(.2,.7,.2,1) both;animation-delay:var(--d,0s)}
.ax .play svg .fade{animation:ax-fade .6s ease both;animation-delay:var(--d,1s)}
.ax .play svg .draw{animation:ax-draw 1.3s ease both;animation-delay:var(--d,0s)}
@keyframes ax-gv{from{transform:scaleY(0)}to{transform:scaleY(1)}}
@keyframes ax-gh{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes ax-fade{from{opacity:0}to{opacity:1}}
@keyframes ax-draw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
@media (prefers-reduced-motion:reduce){.ax .play svg .gv,.ax .play svg .gh,.ax .play svg .gc,.ax .play svg .fade,.ax .play svg .draw{animation:none}}
